package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.Token;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ResolvableDeserializer;
import com.fasterxml.jackson.databind.deser.std.UntypedObjectDeserializer.F_MASK_INT_COERCIONS;
import com.fasterxml.jackson.databind.deser.std.UntypedObjectDeserializer.JsonTokenId;
import com.fasterxml.jackson.databind.deser.std.UntypedObjectDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.std.StdStreamDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class UntypedObjectDeserializer_deserialize_TriageGen1Test {

    private UntypedObjectDeserializer deserializer;
    private JsonParser p;
    private DeserializationContext ctxt;

    @Before
    public void setUp() {
        deserializer = new UntypedObjectDeserializer();
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
    }

    @Test
    public void testDeserialize_StartObject_WithMapDeserializer() throws IOException {
        // Using a subclass to inject private/protected fields via reflection or mocking behavior
        // Since we cannot easily set private fields without reflection, we simulate the logic flow
        UntypedObjectDeserializer spyDeserializer = spy(new UntypedObjectDeserializer());
        // Note: In a real scenario, we'd use reflection to set _mapDeserializer
        // For this test, we assume the logic path for mapObject if _mapDeserializer is null
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_START_OBJECT);
        when(spyDeserializer.mapObject(p, ctxt)).thenReturn("mappedObject");

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals("mappedObject", result);
    }

    @Test
    public void testDeserialize_FieldName_WithMapDeserializer() throws IOException {
        UntypedObjectDeserializer spyDeserializer = spy(new UntypedObjectDeserializer());
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_FIELD_NAME);
        when(spyDeserializer.mapObject(p, ctxt)).thenReturn("mappedField");

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals("mappedField", result);
    }

    @Test
    public void testDeserialize_StartArray_UseJavaArray() throws IOException {
        UntypedObjectDeserializer spyDeserializer = spy(new UntypedObjectDeserializer());
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_START_ARRAY);
        when(ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)).thenReturn(true);
        when(spyDeserializer.mapArrayToArray(p, ctxt)).thenReturn(new Object[]{"item"});

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals(new Object[]{"item"}, result);
    }

    @Test
    public void testDeserialize_StartArray_WithListDeserializer() throws IOException {
        // To test the _listDeserializer != null branch, we'd need reflection to set it.
        // Assuming we can't use reflection here, we test the mapArray fallback.
        UntypedObjectDeserializer spyDeserializer = spy(new UntypedObjectDeserializer());
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_START_ARRAY);
        when(ctxt.isEnabled(DeserializationFeature.USE_JAVA_ARRAY_FOR_JSON_ARRAY)).thenReturn(false);
        when(spyDeserializer.mapArray(p, ctxt)).thenReturn(java.util.Arrays.asList("item"));

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals(java.util.Arrays.asList("item"), result);
    }

    @Test
    public void testDeserialize_EmbeddedObject() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_EMBEDDED_OBJECT);
        Object embedded = new Object();
        when(p.getEmbeddedObject()).thenReturn(embedded);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(embedded, result);
    }

    @Test
    public void testDeserialize_String_WithStringDeserializer() throws IOException {
        // Mocking the _stringDeserializer path via spy if possible, otherwise fallback
        UntypedObjectDeserializer spyDeserializer = spy(new UntypedObjectDeserializer());
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_STRING);
        when(p.getText()).thenReturn("hello");

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals("hello", result);
    }

    @Test
    public void testDeserialize_NumberInt_WithCoercion() throws IOException {
        UntypedObjectDeserializer spyDeserializer = spy(new UntypedObjectDeserializer());
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_NUMBER_INT);
        // We simulate _coerceIntegral via a spy if it were accessible, but here we test the fallback
        when(ctxt.hasSomeOfFeatures(any())).thenReturn(false); 
        when(p.getNumberValue()).thenReturn(123);

        Object result = spyDeserializer.deserialize(p, ctxt);
        assertEquals(123, result);
    }

    @Test
    public void testDeserialize_NumberInt_Standard() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_NUMBER_INT);
        when(ctxt.hasSomeOfFeatures(any())).thenReturn(false);
        when(p.getNumberValue()).thenReturn(456);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(456, result);
    }

    @Test
    public void testDeserialize_NumberFloat_WithBigDecimal() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_NUMBER_FLOAT);
        when(ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)).thenReturn(true);
        java.math.BigDecimal bd = new java.math.BigDecimal("1.23");
        when(p.getDecimalValue()).thenReturn(bd);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(bd, result);
    }

    @Test
    public void testDeserialize_NumberFloat_Standard() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_NUMBER_FLOAT);
        when(ctxt.isEnabled(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)).thenReturn(false);
        when(p.getDoubleValue()).thenReturn(1.23d);

        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(1.23d, (Double) result, 0.001);
    }

    @Test
    public void testDeserialize_True() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_TRUE);
        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(Boolean.TRUE, result);
    }

    @Test
    public void testDeserialize_False() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_FALSE);
        Object result = deserializer.deserialize(p, ctxt);
        assertEquals(Boolean.FALSE, result);
    }

    @Test
    public void testDeserialize_Null() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_NULL);
        Object result = deserializer.deserialize(p, ctxt);
        assertNull(result);
    }

    @Test(expected = JsonMappingException.class)
    public void testDeserialize_InvalidToken_ThrowsException() throws IOException {
        when(p.getCurrentTokenId()).thenReturn(JsonTokenId.ID_END_ARRAY); // Invalid case in switch
        when(ctxt.mappingException(Object.class)).thenThrow(new JsonMappingException(null, "error"));

        deserializer.deserialize(p, ctxt);
    }

    @Test(expected = JsonMappingException.class)
    public void testDeserialize_DefaultCase_ThrowsException() throws IOException {
        // Using a token that falls into default
        when(p.getCurrentTokenId()).thenReturn((JsonTokenId) 999); 
        when(ctxt.mappingException(Object.class)).thenThrow(new JsonMappingException(null, "error"));

        deserializer.deserialize(p, ctxt);
    }
}
